(2309110, 319595, 41574, '<td valign="top">Great pet-shot.</td>', 'Great pet-shot.', '2006-04-13 01:57:28.000000', NULL, 1),
(2309112, 318388, 22301, '<td valign="top">Nice spotlight, but i think cropping out some more of the image such as the poles on the left side and maybe the tree on the right side and some of the foreground would have accentuated the person in the spotlight more</td>', 'Nice spotlight, but i think cropping out some more of the image such as the poles on the left side and maybe the tree on the right side and some of the foreground would have accentuated the person in the spotlight more', '2006-04-13 01:59:02.000000', NULL, 1),
