(2313846, 319118, 44453, '<td valign="top">its a shame about the blured object in the lower left hand corner - otherwise it''s a great image</td>', 'its a shame about the blured object in the lower left hand corner - otherwise it''s a great image', '2006-04-15 08:26:46.000000', NULL, 1),
(2313848, 319663, 44453, '<td valign="top">one of my favourites so far this challenge - well composed</td>', 'one of my favourites so far this challenge - well composed', '2006-04-15 08:29:06.000000', NULL, 1),
(2313869, 318606, 44453, '<td valign="top">I''m going to hazard a guess and say that the other bloke got a better shot, but  it probably wouldn''t go as well as yours in a "candid" competition.</td>', 'I''m going to hazard a guess and say that the other bloke got a better shot, but  it probably wouldn''t go as well as yours in a "candid" competition.', '2006-04-15 08:55:43.000000', NULL, 1),
